# Load packages
library(Biostrings)
library(dplyr)
library(readr)

# Define inputs
# arabidopsis_busco_genes.tsv.tsv generated by BUSCO.
busco_file <- file.path(
  "data",
  "processed",
  "busco",
  "arabidopsis_busco_genes.tsv"
)

# Per-gene GWAS trait table
gwas_file <- file.path(
  "results",
  "gene_trait_table.csv"
)

# TAIR10 protein FASTA used to define the background gene set.
protein_file <- "/path/to/Arabidopsis_thaliana.TAIR10.pep.all.fa"

# Load data
busco <- read.delim(
  busco_file,
  skip = 2,
  header = TRUE
)

gwas_data <- read_csv(
  gwas_file,
  show_col_types = FALSE
)

proteins <- readAAStringSet(
  protein_file
)

# Identify complete and duplicated BUSCO genes.
# Remove transcript suffixes to obtain TAIR10 gene identifiers.
busco_genes <- busco %>%
  filter(
    Status %in% c("Complete", "Duplicated")
  ) %>%
  mutate(
    gene = sub(
      "\\.[0-9]+$",
      "",
      Sequence
    )
  ) %>%
  pull(
    gene
  ) %>%
  unique()

# Identify genes with at least one retained GWAS association.
gwas_genes <- unique(
  gwas_data$gene
)

# Define the background gene set using the TAIR10 protein FASTA.
protein_ids <- names(
  proteins
)

background_genes <- sub(
  "\\.[0-9]+.*$",
  "",
  protein_ids
)

background_genes <- unique(
  background_genes
)

# Construct a gene-level table.
test_df <- data.frame(
  gene = background_genes
)

test_df <- test_df %>%
  mutate(
    busco_gene = gene %in% busco_genes,
    has_gwas_hit = gene %in% gwas_genes
  )

# Construct the 2 × 2 contingency table.
tab <- table(
  BUSCO_gene = test_df$busco_gene,
  GWAS_hit = test_df$has_gwas_hit
)

tab

# Compare BUSCO and non-BUSCO genes using Fisher's exact test.
fisher_result <- fisher.test(
  tab
)

fisher_result

# Calculate the proportion of BUSCO genes with retained GWAS associations.
busco_prop <- mean(
  test_df$has_gwas_hit[
    test_df$busco_gene
  ]
)

busco_prop

# Calculate the proportion of non-BUSCO genes with retained GWAS associations.
nonbusco_prop <- mean(
  test_df$has_gwas_hit[
    !test_df$busco_gene
  ]
)

nonbusco_prop

